async function api(path:string,body?:unknown){const r=await fetch(`/api/dm/${path}`,{cache:"no-store",...(body===undefined?{}:{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)})});const data=await r.json();if(!r.ok||!data.ok)throw new Error(data.error||`HTTP ${r.status}`);return data}
function duration(m:number){return m===0?"off":m<60?`${m} min`:m%60===0?`${m/60} ${m===60?"hour":"hours"}`:`${m} min`}
function remaining(until:number,now:number){const m=Math.max(1,Math.ceil((until-now)/60000));return m<60?`${m}m`:`${Math.floor(m/60)}h ${m%60}m`}
function ago(time:number|null|undefined,now:number){if(!time)return "Not messaged yet";const m=Math.max(0,Math.floor((now-time)/60000));return m<1?"just now":m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`}
